<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Almacenamiento · Simple View</title><style>:root{font-family:Inter,system-ui,sans-serif;color:#172033;background:#f5f7fa}*{box-sizing:border-box}body{margin:0}.wrap{max-width:1200px;margin:auto;padding:24px}.top{display:flex;align-items:center;gap:12px}.top h1{flex:1}.btn{display:inline-block;border:1px solid #ccd3df;background:#fff;border-radius:8px;padding:9px 13px;text-decoration:none;color:#172033;font-weight:650;cursor:pointer}.primary{background:#4f46e5;color:white;border-color:#4f46e5}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card{background:white;border:1px solid #dfe3eb;border-radius:12px;padding:16px;margin-bottom:16px}.metric b{display:block;font-size:24px;margin-top:8px}.status{padding:5px 9px;border-radius:999px;background:#ecfdf3;color:#067647}.status.warning,.status.stale{background:#fffaeb;color:#b54708}.status.critical{background:#fef3f2;color:#b42318}.bar{height:14px;background:#e4e7ec;border-radius:99px;overflow:hidden}.bar i{display:block;height:100%;background:#6366f1}.break{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.break div{padding:10px;background:#f8fafc;border-radius:8px}.break b{display:block}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #e4e7ec;font-size:13px}img{width:54px;height:36px;object-fit:cover;border-radius:5px}.flash{background:#ecfdf3;padding:12px;border-radius:8px;margin-bottom:12px}small{color:#667085}@media(max-width:800px){.grid,.break{grid-template-columns:1fr 1fr}.wrap{padding:12px}}</style></head><body><main class="wrap"><div class="top"><a class="btn" href="/admin">← Panel</a><h1>Gestionar almacenamiento</h1><form method="post" action="{{ route('storage.refresh') }}">@csrf<button class="btn">Actualizar medición</button></form></div>@if(session('status'))<div class="flash">{{ session('status') }}</div>@endif
